db.js.text:
const { Pool } = require("pg");

const pool = new Pool();

// Every read in the service goes through query(). Every write goes through
// write() — it exists so callers get the RETURNING row back in one shape and
// so there is exactly one place a transaction begins.
async function query(text, params) {
  const res = await pool.query(text, params);
  return res.rows;
}

async function write(text, params) {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const res = await client.query(text, params);
    await client.query("COMMIT");
    return res.rows[0];
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }
}

async function withIdempotency(accountId, idempotencyKey, fn) {
  const cached = await query(
    "SELECT response FROM idempotency_keys WHERE account_id = $1 AND key = $2",
    [accountId, idempotencyKey]
  );
  if (cached.length) return JSON.parse(cached[0].response);

  const result = await fn();
  await query(
    "INSERT INTO idempotency_keys (account_id, key, response) VALUES ($1, $2, $3)",
    [accountId, idempotencyKey, JSON.stringify(result)]
  );
  return result;
}

module.exports = { query, write, withIdempotency };

