const express = require("express");
const { sessionUser } = require("./auth");
const accounts = require("./routes/accounts");
const orders = require("./routes/orders");

const idempotencyCache = new Map();

const app = express();
app.use(express.json());

// Resolves the session cookie to a user row and sets req.user for every
// request; requests without a valid session are rejected here.
app.use(sessionUser);

app.use((req, res, next) => {
  if (req.method === "POST") {
    const key = req.get("Idempotency-Key");
    if (!key) return res.status(400).json({ error: "Idempotency-Key required" });

    const cacheKey = `${req.user.id}:${req.path}:${key}`;
    if (idempotencyCache.has(cacheKey)) {
      const cached = idempotencyCache.get(cacheKey);
      return res.status(cached.status).json(cached.body);
    }

    const originalJson = res.json.bind(res);
    res.json = function(data) {
      idempotencyCache.set(cacheKey, { status: res.statusCode, body: data });
      return originalJson(data);
    };
  }
  next();
});

app.use((req, res, next) => {
  const start = Date.now();
  const originalJson = res.json.bind(res);
  const originalEnd = res.end.bind(res);

  res.json = function(data) {
    const duration = Date.now() - start;
    console.log(`${req.method} ${req.path} ${req.user.id} ${res.statusCode} ${duration}ms`);
    return originalJson(data);
  };

  res.end = function(...args) {
    const duration = Date.now() - start;
    console.log(`${req.method} ${req.path} ${req.user.id} ${res.statusCode} ${duration}ms`);
    return originalEnd(...args);
  };

  next();
});

app.use("/accounts", accounts);
app.use("/orders", orders);

app.listen(process.env.PORT || 3000);

