const express = require("express");
const db = require("../db");

const router = express.Router();
const idempotencyCache = new Map();

router.post("/", async (req, res) => {
  const idempotencyKey = req.get("Idempotency-Key");

  if (!idempotencyKey) {
    return res.status(400).json({ error: "Idempotency-Key header required" });
  }

  if (idempotencyCache.has(idempotencyKey)) {
    return res.status(201).json(idempotencyCache.get(idempotencyKey));
  }

  const row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity) VALUES ($1, $2, $3) RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity]
  );

  idempotencyCache.set(idempotencyKey, row);
  res.status(201).json(row);
});

router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row) return res.status(404).end();
  res.json(row);
});

module.exports = router;

turns.text:
If the connection drops mid-transaction, the ROLLBACK in the catch block will also fail because the connection is dead. That second error—from the failed ROLLBACK—is what gets thrown to the caller, masking the original error that caused the problem.

Example: connection drops during `await client.query(text, params)`. The query throws an error. The catch block runs `await client.query("ROLLBACK")`, which also throws because there's no connection. That ROLLBACK error propagates to the caller instead of the original query error. The finally block still releases the dead client.

The fix is to wrap the ROLLBACK in a try-catch to handle connection loss gracefully and throw the original error:

```javascript
catch (err) {
  try {
    await client.query("ROLLBACK");
  } catch (rollbackErr) {
    // connection already dead, ignore
  }
  throw err;
}
```

This preserves the original error for the caller to see and handle properly.

