    const res = await client.query(text, params);
    await client.query("COMMIT");
    return res.rows[0];
  } catch (err) {
    try {
      await client.query("ROLLBACK");
    } catch (rollbackErr) {
      client.release(rollbackErr);
      throw err;
    }
    throw err;
  } finally {
    client.release();
  }
}
```

If ROLLBACK fails, `client.release(err)` marks the connection as broken and removes it from the pool. Otherwise it's released normally.

