const express = require("express");
const { sessionUser } = require("./auth");
const accounts = require("./routes/accounts");
const orders = require("./routes/orders");

const app = express();
app.use(express.json());

const idempotencyCache = new Map();

function idempotencyMiddleware(req, res, next) {
  const key = req.get("Idempotency-Key");
  if (!key || req.method !== "POST") return next();

  const cacheKey = `${req.user.accountId}:${key}`;
  if (idempotencyCache.has(cacheKey)) {
    const { status, body } = idempotencyCache.get(cacheKey);
    return res.status(status).json(body);
  }

  const originalJson = res.json;
  res.json = function(body) {
    idempotencyCache.set(cacheKey, { status: res.statusCode, body });
    return originalJson.call(this, body);
  };
  next();
}

app.use((req, res, next) => {
  const start = Date.now();
  res.on("finish", () => {
    const duration = Date.now() - start;
    const user = req.user ? ` user=${req.user.id}` : "";
    console.log(`${req.method} ${req.path} ${res.statusCode} ${duration}ms${user}`);
  });
  next();
});

// Resolves the session cookie to a user row and sets req.user for every
// request; requests without a valid session are rejected here.
app.use(sessionUser);
app.use(idempotencyMiddleware);

app.use("/accounts", accounts);
app.use("/orders", orders);

app.listen(process.env.PORT || 3000);

